        import org.apache.log4j.Logger;

        Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to Start Step!!!");
        }

        import org.apache.log4j.Logger;

        import sailpoint.object.Identity;

        Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to FindTerminatingUser Step!!!");
        }
        Identity identityObject = null;
        logger.debug("Alpha-Workflow-Immediate-Termination - FindTerminatingUser Step -> QuickLink Identity ID : "+quickLinkIdentityId);
        if (quickLinkIdentityId != null) {
        identityObject = context.getObjectById(Identity.class,quickLinkIdentityId);
        if (identityObject != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination - FindTerminatingUser Step -> Identity : "+identityObject.getName());
        workflow.put("terminateIdentity", identityObject.getName());
        }
        if (identityObject != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination - FindTerminatingUser Step -> Decaching the Identity Object");
        context.decache(identityObject);
        }
        }
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> FindTerminatingUser Step is Ended!!!");
        }

          if (isSubmitted.equalsIgnoreCase("true")) {
          return true;
          }
          else {
          return false;
