        import java.text.SimpleDateFormat;
        import java.util.Date;

        import org.apache.log4j.Logger;

        import sailpoint.object.Identity;

        Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to UpdateTerminationDate Step!!!");
        }
        Identity identityObject = null;
        logger.debug("Alpha-Workflow-Immediate-Termination - UpdateTerminationDate Step -> TerminateIdentity : "+workflow.get("terminateIdentity"));
        if (workflow.get("terminateIdentity") != null) {
        identityObject = context.getObjectByName(Identity.class,workflow.get("terminateIdentity"));
        if (identityObject != null) {
        Date currentDate = new Date();
        String dateFormat = null;
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        dateFormat = sdf.format(currentDate);
        logger.debug("Alpha-Workflow-Immediate-Termination - UpdateTerminationDate Step -> Formatted TerminationDate : "+dateFormat);
        identityObject.setAttribute("terminationDate", dateFormat);
        context.saveObject(identityObject);
        context.commitTransaction();
        }
        if (identityObject != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination - UpdateTerminationDate Step -> Decaching the Identity Object");
        context.decache(identityObject);
        }
        }
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> UpdateTerminationDate Step is Ended!!!");
        }

